@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ProductScreen(
    productId: String = "iphone",
    onNavigateBack: () -> Unit = {},
    onContinue: () -> Unit = {}
) {
    val product = remember(productId) {
        productCatalog[productId] ?: productCatalog.getValue("iphone")
    }

    Scaffold(
        containerColor = Color.White,
        topBar = {
            CenterAlignedTopAppBar(
                title = {
                    Text(
                        text = product.title,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                },
                navigationIcon = {
                    IconButton(onClick = onNavigateBack) {
                        Image(
                            painter = painterResource(id = R.drawable.back_arrow),
                            contentDescription = "Back",
                            modifier = Modifier.size(18.dp)
                        )
                    }
                },
                colors = TopAppBarDefaults.centerAlignedTopAppBarColors(containerColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFF8DF07D))
                    .padding(horizontal = 12.dp, vertical = 12.dp),
                horizontalArrangement = Arrangement.SpaceEvenly,
                verticalAlignment = Alignment.CenterVertically
            ) {
                product.badges.forEach { badge ->
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(text = badge.icon, fontSize = 14.sp)
                        Text(text = badge.text, fontSize = 12.sp, color = Color(0xFF102000), fontWeight = FontWeight.Medium)
                    }
                }
            }

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp)
                    .height(220.dp)
                    .background(Color.White, RoundedCornerShape(20.dp)),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painter = painterResource(id = product.imageRes),
                    contentDescription = "Product image",
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(24.dp),
                    contentScale = ContentScale.Fit
                )
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                horizontalArrangement = Arrangement.End
            ) {
                Surface(
                    shape = RoundedCornerShape(16.dp),
                    color = Color.White,
                    tonalElevation = 0.dp,
                    shadowElevation = 1.dp
                ) {
                    Text(
                        text = "1/4",
                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp),
                        fontSize = 12.sp,
                        color = Color(0xFF666666)
                    )
                }
            }

            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp)
            ) {
                Text(
                    text = "From as low as",
                    fontSize = 12.sp,
                    color = Color(0xFF8A8A8A)
                )
                Text(
                    text = product.price,
                    fontSize = 28.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color.Black
                )
                Text(
                    text = product.subtitle,
                    fontSize = 13.sp,
                    color = Color(0xFF222222),
                    modifier = Modifier.padding(top = 4.dp)
                )
            }

            SectionTitle(title = "WHERE DO YOU WANT TO SHOP?")
            ShopLocationCard(locationText = product.locationText)

            SectionTitle(title = "MAKE A DEAL? PARTNER MERCHANTS")
            product.merchants.forEach { merchant ->
                MerchantCard(merchantName = merchant.name)
            }

            SectionTitle(title = "FEATURES")
            product.features.forEach { feature ->
                FeatureItem(title = feature.title, text = feature.text)
            }

            SectionTitle(title = "PRODUCT SPECIFICATIONS")
            product.specs.forEach { spec ->
                SpecItem(label = spec.label, value = spec.value)
            }

            Spacer(modifier = Modifier.height(96.dp))
        }

        Box(
            modifier = Modifier
                .fillMaxSize(),
            contentAlignment = Alignment.BottomCenter
        ) {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                shape = RoundedCornerShape(18.dp),
                color = Color.White,
                shadowElevation = 3.dp
            ) {
                Row(
                    modifier = Modifier.padding(16.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(text = "From as low as", fontSize = 11.sp, color = Color(0xFF8A8A8A))
                        Text(text = product.price, fontSize = 22.sp, fontWeight = FontWeight.Bold)
                        Text(text = "per month", fontSize = 11.sp, color = Color(0xFF8A8A8A))
                    }
                    Button(
                        onClick = onContinue,
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF7BF179)),
                        shape = RoundedCornerShape(16.dp),
                        contentPadding = PaddingValues(horizontal = 22.dp, vertical = 14.dp)
                    ) {
                        Text(text = "Continue", color = Color(0xFF102000), fontWeight = FontWeight.SemiBold)
                    }
                }
            }
        }
    }
}

@Composable
private fun SectionTitle(title: String) {
    Text(
        text = title,
        modifier = Modifier.padding(horizontal = 16.dp, vertical = 12.dp),
        fontSize = 11.sp,
        color = Color(0xFF8A8A8A),
        fontWeight = FontWeight.Bold
    )
}

@Composable
private fun ShopLocationCard(locationText: String) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp),
        shape = RoundedCornerShape(14.dp),
        color = Color.White,
        shadowElevation = 1.dp
    ) {
        Row(
            modifier = Modifier.padding(14.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(text = "", fontSize = 16.sp)
            Spacer(modifier = Modifier.width(10.dp))
            Column(modifier = Modifier.weight(1f)) {
                Text(text = locationText, fontSize = 13.sp, fontWeight = FontWeight.Medium)
            }
            Text(text = "⌄", fontSize = 18.sp, color = Color(0xFF777777))
        }
    }
}

@Composable
private fun MerchantCard(
    merchantName: String
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 6.dp),
        shape = RoundedCornerShape(14.dp),
        color = Color.White,
        shadowElevation = 1.dp
    ) {
        Column(modifier = Modifier.padding(14.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Column(modifier = Modifier.weight(1f)) {
                    Text(text = merchantName, fontSize = 14.sp, fontWeight = FontWeight.SemiBold)
                    Text(
                        text = "United Availability",
                        fontSize = 11.sp,
                        color = Color(0xFF7BF179),
                        modifier = Modifier.padding(top = 2.dp)
                    )
                }
                Text(text = "⌄", fontSize = 18.sp, color = Color(0xFF777777))
            }
            Text(
                text = "From ₱1,200 | 12 months\n₱6,000 total repayable",
                fontSize = 11.sp,
                color = Color(0xFF666666),
                modifier = Modifier.padding(top = 8.dp)
            )
        }
    }
}

@Composable
