@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ShopScreen(
    onNavigateToProduct: (String) -> Unit = {},
    onNavigateToSearch: () -> Unit = {}
) {
    var searchQuery by remember { mutableStateOf("") }

    Scaffold(
        containerColor = Color.White,
        topBar = {
            CenterAlignedTopAppBar(
                title = {
                    Image(
                        painter = painterResource(id = R.drawable.frame_134),
                        contentDescription = "Logo",
                        modifier = Modifier.size(40.dp)
                    )
                },
                navigationIcon = {
                    IconButton(onClick = { /* Profile */ }) {
                        Icon(
                            painter = painterResource(id = R.drawable.user_icon), 
                            contentDescription = "Profile", 
                            modifier = Modifier.size(24.dp),
                            tint = Color.Unspecified
                        )
                    }
                },
                actions = {
                    IconButton(onClick = { /* Notifications */ }) {
                        Icon(
                            painter = painterResource(id = R.drawable.notification_icon), 
                            contentDescription = "Notifications", 
                            modifier = Modifier.size(24.dp),
                            tint = Color.Unspecified
                        )
                    }
                },
                colors = TopAppBarDefaults.centerAlignedTopAppBarColors(containerColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
        ) {
            // Search Bar
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 24.dp, vertical = 8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    placeholder = { Text("Search for product", color = Color.Gray) },
                    leadingIcon = { Icon(Icons.Default.Search, contentDescription = null, tint = Color.Gray) },
                    modifier = Modifier
                        .weight(1f)
                        .clickable { onNavigateToSearch() },
                    enabled = false, // Make it look like a button
                    shape = RoundedCornerShape(12.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        disabledBorderColor = Color(0xFFF5F5F5),
                        disabledPlaceholderColor = Color.Gray,
                        disabledLeadingIconColor = Color.Gray,
                        disabledContainerColor = Color(0xFFF9F9F9)
                    ),
                    singleLine = true
                )
                Spacer(modifier = Modifier.width(12.dp))
                Box(
                    modifier = Modifier
                        .size(56.dp)
                        .clip(RoundedCornerShape(12.dp))
                        .background(Color(0xFF7BF179))
                        .clickable { /* Filter */ },
                    contentAlignment = Alignment.Center
                ) {
                    Icon(Icons.Default.Tune, contentDescription = "Filter", tint = Color(0xFF102000))
                }
            }

            // Banner - The New Shoes (Promotional Card)
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(250.dp)
                    .padding(horizontal = 16.dp, vertical = 8.dp),
                shape = RoundedCornerShape(24.dp),
                colors = CardDefaults.cardColors(containerColor = Color(0xFF0A2000))
            ) {
                Box(modifier = Modifier.fillMaxSize()) {
                    // Decorative light green base for shoes
                    Box(
                        modifier = Modifier
                            .size(width = 140.dp, height = 120.dp)
                            .align(Alignment.BottomEnd)
                            .padding(bottom = 0.dp, end = 0.dp)
                            .background(
                                color = Color(0xFF7BF179),
                                shape = RoundedCornerShape(topStart = 24.dp)
                            )
                    )

                    Column(
                        modifier = Modifier
                            .padding(24.dp)
                            .align(Alignment.TopStart)
                    ) {
                        Text(
                            text = "The New Shoes",
                            color = Color.White,
                            fontSize = 28.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = "Shop this season's Top Silhouette",
                            color = Color.LightGray,
                            fontSize = 14.sp,
                            modifier = Modifier.padding(vertical = 8.dp)
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                        Button(
                            onClick = { /* Shop Now */ },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF7BF179)),
                            shape = RoundedCornerShape(12.dp),
                            contentPadding = PaddingValues(horizontal = 24.dp, vertical = 12.dp)
                        ) {
                            Text("Shop Now", color = Color(0xFF102000), fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        }
                    }

                    // Sneaker Image
                    Image(
                        painter = painterResource(id = R.drawable.promotional_shoes),
                        contentDescription = null,
                        modifier = Modifier
                            .size(240.dp) // Increased size
                            .align(Alignment.BottomEnd)
                            .offset(x = 20.dp, y = 0.dp), // Adjusted offset
                        contentScale = ContentScale.Fit
                    )

                    // Carousel Dots (Lower left)
                    Row(
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(start = 24.dp, bottom = 24.dp),
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Box(modifier = Modifier.size(6.dp).background(Color.White, CircleShape))
                        Box(modifier = Modifier.size(6.dp).background(Color.Gray.copy(alpha = 0.5f), CircleShape))
                        Box(modifier = Modifier.size(6.dp).background(Color.Gray.copy(alpha = 0.5f), CircleShape))
                    }
                }
            }

            // Shop By Category
            SectionHeader(title = "Shop By Category")
            LazyRow(
                contentPadding = PaddingValues(horizontal = 24.dp),
                horizontalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                item { CategoryItem("Phone", R.drawable.img_iphone) }
                item { CategoryItem("Headphones", R.drawable.img_headphones) }
                item { CategoryItem("Apparel", R.drawable.img_sneakers) }
                item { CategoryItem("Phone", R.drawable.img_iphone) }
            }

            // Popular Brands
            SectionHeader(title = "Popular Brands")
            LazyRow(
                contentPadding = PaddingValues(horizontal = 24.dp),
                horizontalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                item { BrandItem("Apple", R.drawable.logo_apple) }
                item { BrandItem("Jordan", R.drawable.logo_nike) } // Using Nike for Jordan placeholder
                item { BrandItem("Adidas", R.drawable.logo_nike) } // Using Nike for Adidas placeholder
            }

            // Recommended For You
            SectionHeader(title = "Recommended For You")
            LazyRow(
                contentPadding = PaddingValues(horizontal = 24.dp),
                horizontalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                item { ProductItem("iPhone 12 Pro...", "₱1,200 × 24 mo", R.drawable.img_iphone) }
                item { ProductItem("Headphones", "₱1,200 × 24 mo", R.drawable.img_headphones) }
                item { ProductItem("Sneakers", "₱1,200 × 24 mo", R.drawable.img_sneakers) }
            }

            // Best Sellers
            SectionHeader(title = "Best Sellers")
            LazyRow(
                contentPadding = PaddingValues(horizontal = 24.dp, vertical = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                item { ProductItem("Surface Laptop", "₱1,200 × 24 mo", R.drawable.img_iphone) } // Placeholder
                item { ProductItem("iPhone 12 Pro...", "₱1,200 × 24 mo", R.drawable.img_iphone) }
                item { ProductItem("PS4 Play Stat...", "₱1,200 × 24 mo", R.drawable.img_headphones) } // Placeholder
            }

            Spacer(modifier = Modifier.height(32.dp))
        }
    }
}

@Composable
