@Composable
fun ProductItem(name: String, price: String, imageRes: Int) {
    Box(
        modifier = Modifier
            .width(160.dp)
            .clip(RoundedCornerShape(16.dp))
            .background(Color(0xFFF9F9F9))
            .padding(12.dp)
